<template><section><el-alert v-if="error" :title="error" type="error" :closable="false" /><div v-if="pool" class="ops-metrics"><article class="ops-metric"><small>获批发放总池 · 元</small><strong>{{ money(pool.total) }}</strong></article><article class="ops-metric"><small>已分配额度 · 元</small><strong>{{ money(pool.allocated) }}</strong></article><article class="ops-metric"><small>待分配额度 · 元</small><strong>{{ money(pool.available) }}</strong></article></div><div class="ops-toolbar"><p class="ops-muted">发放额度属于平台服务授权，与供应商现金余额分别管理。</p><div class="ops-actions"><el-button v-if="can('pool.adjust')" size="small" @click="open('pool')">调整发放总池</el-button><el-button v-if="can('allowance.grant')" size="small" type="primary" @click="open('grant')">发放服务额度</el-button><el-button size="small" :loading="loading" @click="load">刷新</el-button></div></div><section v-if="can('allowance.read')" class="ops-panel ops-table"><h2>用户服务账户</h2><el-table :data="accounts" v-loading="loading" empty-text="暂无服务账户"><el-table-column prop="userId" label="用户 ID" width="140" /><el-table-column label="账户状态" width="110"><template slot-scope="s">{{ s.row.frozen ? "已冻结" : "可用" }}</template></el-table-column><el-table-column prop="available" label="可用（元）" min-width="130" /><el-table-column prop="reserved" label="预占（元）" min-width="110" /><el-table-column prop="spent" label="累计使用（元）" min-width="150" /><el-table-column label="操作" min-width="140"><template slot-scope="s"><el-button v-if="can('allowance.grant')" type="text" @click="open('grant', s.row)">授额</el-button><el-button v-if="can('allowance.freeze')" type="text" @click="open('freeze', s.row)">{{ s.row.frozen ? '解冻' : '冻结' }}</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="changePage" /></section><section v-if="can('allowance.read') || can('allowance.review')" class="ops-panel ops-table"><h2>用户额度申请</h2><p class="ops-muted">额度由平台运维统一下发，无需用户申请。此处仅处理历史申请，保留内部兼容；发放金额仍由授权岗位按政策决定。</p><el-table :data="requests" v-loading="requestsLoading" empty-text="没有待处理的额度申请"><el-table-column prop="createdAt" label="提交时间" min-width="170" /><el-table-column prop="userId" label="用户 ID" width="120" /><el-table-column prop="workspaceId" label="空间" min-width="120" /><el-table-column label="期望金额（元）" min-width="120"><template slot-scope="s">{{ s.row.requestedAmount == null ? '未指定' : money(s.row.requestedAmount) }}</template></el-table-column><el-table-column prop="reason" label="申请说明" min-width="220" /><el-table-column label="操作" width="150"><template slot-scope="s"><el-button v-if="can('allowance.grant')" type="text" @click="approve(s.row)">批准发放</el-button><el-button v-if="can('allowance.review')" type="text" @click="reject(s.row)">不通过</el-button></template></el-table-column></el-table></section><el-dialog :title="dialogTitle" :visible.sync="dialog" width="min(500px,92vw)" :close-on-click-modal="false" :show-close="!saving"><el-form class="ops-form" label-width="95px" @submit.native.prevent="save"><el-form-item v-if="action !== 'pool'" label="用户 ID"><el-input v-model="form.userId" :disabled="action === 'freeze'" /></el-form-item><el-form-item v-if="action !== 'freeze'" :label="action === 'pool' ? '调整金额' : '发放金额'"><el-input v-model="form.amount" placeholder="元" /><p class="ops-muted">{{ action === 'pool' ? '负数仅可收回未分配的额度。' : '发放不得超过剩余总池和岗位授权上限。' }}</p></el-form-item><el-form-item label="操作原因"><el-input v-model="form.reason" type="textarea" maxlength="500" :rows="3" /></el-form-item><p v-if="action === 'freeze'" class="ops-muted">{{ form.frozen ? '冻结后停止新付费调用；历史记录和已准入调用仍按原规则处理。' : '恢复服务账户的新调用资格，仍受可用额度和凭据状态限制。' }}</p></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认{{ dialogTitle }}</el-button></span></el-dialog></section></template>
<script>
import { operations } from '@/apis/platform';
import { hasPermission } from '@/security/session';
import { allowanceAmount, newOperationId } from '@/utils/allowance';
export default {
  data() { return { pool: null, accounts: [], loading: false, error: '', page: 1, total: 0, dialog: false, action: 'grant', form: {}, saving: false, saveError: '', generation: 0, requests: [], requestsLoading: false, requestGeneration: 0 }; },
  computed: { dialogTitle() { return this.action === 'pool' ? '调整总池' : this.action === 'freeze' ? (this.form.frozen ? '冻结账户' : '解冻账户') : '发放额度'; } },
  created() { this.load(); }, beforeDestroy() { this.generation++; this.requestGeneration++; },
  methods: {
    money: allowanceAmount, can(permission) { return hasPermission(this.$store.state.userInfo, permission); },
    async loadRequests() { const generation = ++this.requestGeneration; this.requestsLoading = true; try { const result = await operations.allowanceRequests({ page: 1, limit: 50 }); if (generation === this.requestGeneration) this.requests = result.list || []; } catch (error) { if (generation === this.requestGeneration) this.error = error.message; } finally { if (generation === this.requestGeneration) this.requestsLoading = false; } },
    async approve(row) {
      let amount;
      try { const result = await this.$prompt(`批准发放后将从发放总池扣除额度并记入用户账户。用户期望 ${row.requestedAmount == null ? '未指定' : row.requestedAmount + ' 元'}，实际发放由你决定。`, '批准额度申请', { inputPlaceholder: '实际发放金额（元）', inputValidator: value => /^\d+(\.\d{1,6})?$/.test(String(value)) && Number(value) > 0 || '请填写大于零的金额' }); amount = String(result.value).trim(); } catch (_) { return; }
      let reason;
      try { const result = await this.$prompt('请填写发放原因，将记入额度流水。', '发放原因', { inputPlaceholder: '例如：按试用政策发放', inputValidator: value => !!String(value).trim() || '请填写原因' }); reason = String(result.value).trim(); } catch (_) { return; }
      try { await operations.approveAllowance(row.id, { requestId: `allowance-approval-${row.id}`, amount, reason }); this.$message.success('已发放额度'); await Promise.all([this.loadRequests(), this.load()]); } catch (error) { this.$message.error(error.message); }
    },
    async reject(row) {
      let reason;
      try { const result = await this.$prompt('不通过原因会显示给用户。', '不通过额度申请', { inputPlaceholder: '例如：不符合当前发放政策', inputValidator: value => !!String(value).trim() || '请填写原因' }); reason = String(result.value).trim(); } catch (_) { return; }
      try { await operations.rejectAllowance(row.id, reason); this.$message.success('已处理'); await this.loadRequests(); } catch (error) { this.$message.error(error.message); }
    },
    async load() { const generation = ++this.generation; this.loading = true; this.error = ''; try { const [pool, accounts] = await Promise.all([this.can('pool.read') ? operations.pool() : null, this.can('allowance.read') ? operations.accounts({ page: this.page, limit: 20 }) : null]); if (generation !== this.generation) return; this.pool = pool; this.accounts = accounts?.list || []; this.total = accounts?.total || 0; if (this.can('allowance.read') || this.can('allowance.review')) await this.loadRequests(); } catch (error) { if (generation === this.generation) this.error = error.message; } finally { if (generation === this.generation) this.loading = false; } },
    changePage(page) { this.page = page; this.load(); },
    open(action, row = {}) { this.action = action; this.form = { requestId: newOperationId(), userId: row.userId || '', amount: '', reason: '', frozen: !row.frozen }; this.saveError = ''; this.dialog = true; },
    async save() { if (this.saving) return; if (!this.form.reason.trim() || (this.action !== 'pool' && !/^\d+$/.test(String(this.form.userId)))) { this.saveError = '请填写有效用户 ID 和操作原因'; return; } if (this.action !== 'freeze' && (!/^-?\d+(\.\d{1,6})?$/.test(this.form.amount) || Number(this.form.amount) === 0 || (this.action === 'grant' && Number(this.form.amount) < 0))) { this.saveError = '请填写有效的非零金额，发放金额必须大于零'; return; } this.saving = true; this.saveError = ''; try { const { requestId, userId, amount, reason, frozen } = this.form; if (this.action === 'pool') await operations.adjustPool({ requestId, amount, reason }); else if (this.action === 'freeze') await operations.freeze({ requestId, userId, frozen, reason }); else await operations.grant({ requestId, userId, amount, reason }); this.dialog = false; this.$message.success('操作已记录'); await this.load(); } catch (error) { this.saveError = error.message; } finally { this.saving = false; } },
  },
};
</script>
